INSERT INTO findings (id, finding_id, aws_account_id, assessment_id, control_id, title, description, category, severity, resource_type, resource_id, region, evidence, business_risk, recommendation, owner_id, status, due_date, created_at) VALUES
  ('00000000-0000-0000-0001-000000000017', 'F-1017', '00000000-0000-0000-0000-000000000200', NULL, (SELECT id FROM controls WHERE control_id = 'OBS-001'), 'Multiple CloudWatch log groups have no retention policy', 'Twelve CloudWatch log groups in the development account have no retention policy, leading to unbounded storage growth.', 'Observability', 'MEDIUM', 'CloudWatch', '12 CloudWatch log groups', 'us-east-1', '12 log groups with retention=NeverExpire. Total storage: 312 GB. Estimated monthly waste: $156.', 'Unbounded log retention causes unnecessary storage costs and slower log queries over time.', 'Set 30-day retention for dev log groups. Implement a tag-based policy to enforce retention on new log groups.', '00000000-0000-0000-0000-000000000012', 'OPEN', '2026-09-25', '2026-08-03T14:00:00Z'),
  ('00000000-0000-0000-0001-000000000018', 'F-1018', '00000000-0000-0000-0000-000000000100', NULL, (SELECT id FROM controls WHERE control_id = 'IAM-003'), 'IAM access key older than 90 days detected', 'An IAM access key used for CI/CD deployment is older than 90 days and should be rotated.', 'IAM', 'MEDIUM', 'IAM', 'AKIA-PROD-DEPLOY-KEY', 'us-east-1', 'Access key AKIA-PROD-DEPLOY-KEY created 2026-03-10. Last used: 2026-08-19. Age: 162 days.', 'Long-lived access keys increase the window of exposure if compromised. Key rotation is a security best practice.', 'Rotate the access key. Consider migrating to OIDC-based federation for CI/CD to eliminate long-lived keys entirely.', '00000000-0000-0000-0000-000000000013', 'OPEN', '2026-09-14', '2026-08-07T12:00:00Z'),
  ('00000000-0000-0000-0001-000000000019', 'F-1019', '00000000-0000-0000-0000-000000000200', NULL, (SELECT id FROM controls WHERE control_id = 'S3-001'), 'S3 bucket lacks server-side encryption with KMS', 'An S3 bucket containing application logs does not use KMS-managed server-side encryption.', 'S3', 'MEDIUM', 'S3', 's3-dev-application-logs', 'us-east-1', 'Bucket s3-dev-application-logs: SSE=SSE-S3 (AES-256), no KMS encryption. Bucket contains 45 GB of application logs.', 'Without KMS encryption, data at rest relies on S3 default encryption which may not meet compliance requirements for audit log protection.', 'Enable SSE-KMS with a customer-managed key. Update bucket policy to require KMS encryption for all new objects.', '00000000-0000-0000-0000-000000000012', 'OPEN', '2026-09-22', '2026-08-04T09:00:00Z'),
  ('00000000-0000-0000-0001-000000000020', 'F-1020', '00000000-0000-0000-0000-000000000300', NULL, (SELECT id FROM controls WHERE control_id = 'EKS-005'), 'EKS cluster missing recommended managed add-on', 'The test EKS cluster is missing the AWS Load Balancer Controller add-on, affecting ingress and service functionality.', 'EKS', 'MEDIUM', 'EKS', 'eks-test-main', 'us-east-1', 'EKS add-ons for eks-test-main: vpc-cni (installed), kube-proxy (installed), coredns (installed). aws-load-balancer-controller: not installed.', 'Without the AWS Load Balancer Controller, ingress and type=LoadBalancer services do not provision ALBs correctly, affecting application routing.', 'Install the AWS Load Balancer Controller as a managed EKS add-on. Verify IAM role permissions for the controller.', '00000000-0000-0000-0000-000000000012', 'OPEN', '2026-09-30', '2026-08-02T11:00:00Z'),
  ('00000000-0000-0000-0001-000000000021', 'F-1021', '00000000-0000-0000-0000-000000000200', NULL, (SELECT id FROM controls WHERE control_id = 'NET-001'), 'Development VPC lacks flow logs', 'The development VPC does not have flow logs enabled, limiting network debugging capability.', 'Networking', 'MEDIUM', 'VPC', 'vpc-dev-main', 'us-east-1', 'VPC vpc-dev-main: 0 flow log configurations. VPC has 4 subnets and hosts 12 EC2 instances.', 'Without flow logs, network issues in the development environment are harder to diagnose, slowing down development velocity.', 'Enable VPC Flow Logs to CloudWatch Logs with 30-day retention for the development VPC.', '00000000-0000-0000-0000-000000000012', 'OPEN', '2026-10-01', '2026-08-01T13:00:00Z'),
  ('00000000-0000-0000-0001-000000000022', 'F-1022', '00000000-0000-0000-0000-000000000200', NULL, NULL, 'RDS instance lacks multi-AZ deployment', 'A development RDS instance is running in single-AZ mode, reducing availability.', 'Database', 'MEDIUM', 'RDS', 'db-dev-users-01', 'us-east-1', 'RDS db-dev-users-01: MultiAZ=false, AZ=us-east-1a. Instance class: db.t3.medium. No read replica configured.', 'Single-AZ databases have no automatic failover and will experience downtime during AZ outages or maintenance.', 'Enable Multi-AZ for the RDS instance. For dev environments, consider if the availability tradeoff justifies the cost.', '00000000-0000-0000-0000-000000000011', 'OPEN', '2026-09-28', '2026-08-03T10:00:00Z'),
  ('00000000-0000-0000-0001-000000000023', 'F-1023', '00000000-0000-0000-0000-000000000200', NULL, NULL, 'EC2 instance running with outdated instance type', 'An EC2 build agent is running on a previous-generation instance type (m4.large) with suboptimal price-performance.', 'Compute', 'MEDIUM', 'EC2', 'i-dev-build-agent-03', 'us-east-1', 'Instance i-dev-build-agent-03: type=m4.large, vCPUs=2, RAM=8GB. Equivalent m6i.large: 15% cheaper, 20% better performance.', 'Older instance types cost more and perform less than current generations, leading to unnecessary spend.', 'Migrate to m6i.large or m7i.large. Use EC2 Fleet or a blue-green replacement to minimize downtime.', '00000000-0000-0000-0000-000000000012', 'OPEN', '2026-10-05', '2026-07-30T09:00:00Z'),
  ('00000000-0000-0000-0001-000000000024', 'F-1024', '00000000-0000-0000-0000-000000000100', NULL, NULL, 'Lambda function has no dead-letter queue configured', 'A production Lambda function processing orders has no dead-letter queue, meaning failed events are silently lost.', 'Compute', 'MEDIUM', 'Lambda', 'prod-order-processor', 'us-east-1', 'Lambda prod-order-processor: DeadLetterConfig=null. Invocation errors in last 7 days: 23. Failed events: unrecoverable.', 'Failed order processing events are lost without a DLQ, leading to silent data loss and customer order failures.', 'Configure an SQS dead-letter queue. Add CloudWatch alarms on DLQ depth and Lambda error rate.', '00000000-0000-0000-0000-000000000011', 'OPEN', '2026-09-19', '2026-08-05T14:00:00Z'),
  ('00000000-0000-0000-0001-000000000025', 'F-1025', '00000000-0000-0000-0000-000000000300', NULL, (SELECT id FROM controls WHERE control_id = 'S3-002'), 'S3 bucket lacks versioning for data protection', 'An S3 bucket storing test artifacts does not have versioning enabled, preventing recovery from accidental overwrites.', 'S3', 'MEDIUM', 'S3', 's3-test-artifacts', 'us-east-1', 'Bucket s3-test-artifacts: Versioning=Suspended. MFA Delete=disabled. Bucket contains 1,240 test report objects.', 'Without versioning, accidental overwrites or deletes are irreversible, potentially losing test artifacts and reports.', 'Enable versioning on the bucket. Consider enabling MFA delete for additional protection of critical artifacts.', '00000000-0000-0000-0000-000000000012', 'OPEN', '2026-10-10', '2026-07-28T10:00:00Z'),
  ('00000000-0000-0000-0001-000000000026', 'F-1026', '00000000-0000-0000-0000-000000000200', NULL, (SELECT id FROM controls WHERE control_id = 'IAM-004'), 'IAM password policy does not meet complexity requirements', 'The IAM password policy for the development account does not enforce minimum length or complexity requirements.', 'IAM', 'MEDIUM', 'IAM', 'IAM Password Policy', 'us-east-1', 'Password policy: MinimumLength=8, RequireSymbols=false, RequireNumbers=false, MaxAge=0 (no rotation).', 'Weak password policies increase the risk of credential compromise through brute-force or dictionary attacks.', 'Update the password policy: minimum 14 characters, require uppercase, lowercase, numbers, symbols, and 90-day rotation.', '00000000-0000-0000-0000-000000000013', 'OPEN', '2026-09-21', '2026-08-04T11:00:00Z'),
  ('00000000-0000-0000-0001-000000000027', 'F-1027', '00000000-0000-0000-0000-000000000100', NULL, (SELECT id FROM controls WHERE control_id = 'OBS-002'), 'CloudWatch alarm has no notification action configured', 'A CloudWatch alarm monitoring production CPU utilization has no SNS notification action, so alerts are never sent.', 'Observability', 'MEDIUM', 'CloudWatch', 'CW-Alarm-Prod-CPU-High', 'us-east-1', 'Alarm CW-Alarm-Prod-CPU-High: Threshold=80%, Period=5min. AlarmActions=[], OKActions=[]. Triggered 3 times in last 30 days.', 'Critical alarms without notification actions are effectively silent, meaning the team will not be alerted to production issues.', 'Attach an SNS topic with email and Slack/PagerDuty subscriptions to the alarm actions.', '00000000-0000-0000-0000-000000000011', 'OPEN', '2026-09-24', '2026-08-06T10:00:00Z'),
  ('00000000-0000-0000-0001-000000000028', 'F-1028', '00000000-0000-0000-0000-000000000200', NULL, (SELECT id FROM controls WHERE control_id = 'EKS-005'), 'EKS cluster has no network policies enforced', 'The development EKS cluster has no network policies, allowing unrestricted pod-to-pod communication.', 'EKS', 'MEDIUM', 'EKS', 'eks-dev-main', 'us-east-1', 'EKS eks-dev-main: Calico/Cilium not installed. 0 NetworkPolicy resources across all namespaces. 67 pods with unrestricted access.', 'Without network policies, a compromised pod can access all other pods in the cluster, increasing lateral movement risk.', 'Install a CNI plugin supporting network policies (Calico or Cilium). Start with a default-deny policy and add allow rules per service.', '00000000-0000-0000-0000-000000000012', 'OPEN', '2026-10-15', '2026-07-29T09:00:00Z'),
  ('00000000-0000-0000-0001-000000000029', 'F-1029', '00000000-0000-0000-0000-000000000300', NULL, NULL, 'RDS instance lacks automated minor version upgrade', 'A test RDS instance has auto minor version upgrade disabled, meaning security patches are not automatically applied.', 'Database', 'MEDIUM', 'RDS', 'db-test-config-01', 'us-east-1', 'RDS db-test-config-01: AutoMinorVersionUpgrade=false. Current engine version: 15.3. Available: 15.4 (security patch).', 'Missing database patches can leave the instance vulnerable to known CVEs that have available fixes.', 'Enable auto minor version upgrade. Schedule upgrades during the defined maintenance window.', '00000000-0000-0000-0000-000000000011', 'OPEN', '2026-10-12', '2026-07-27T11:00:00Z'),
  ('00000000-0000-0000-0001-000000000030', 'F-1030', '00000000-0000-0000-0000-000000000100', NULL, NULL, 'API Gateway stage has no access logging enabled', 'A production API Gateway stage does not have access logging enabled, preventing API request auditing.', 'Observability', 'MEDIUM', 'API Gateway', 'api-prod-orders / prod stage', 'us-east-1', 'API Gateway api-prod-orders, stage "prod": accessLogSettings=null. Stage receives ~2M requests/day.', 'Without access logs, API abuse, errors, and security events cannot be investigated.', 'Enable access logging to CloudWatch Logs with a JSON format. Set 90-day retention.', '00000000-0000-0000-0000-000000000011', 'OPEN', '2026-09-29', '2026-07-31T13:00:00Z'),
  ('00000000-0000-0000-0001-000000000031', 'F-1031', '00000000-0000-0000-0000-000000000200', NULL, (SELECT id FROM controls WHERE control_id = 'SEC-004'), 'EC2 security group allows all outbound traffic', 'A security group allows unrestricted outbound traffic to 0.0.0.0/0 on all ports.', 'Security', 'MEDIUM', 'EC2', 'sg-dev-default', 'us-east-1', 'SG sg-dev-default: outbound rule 0.0.0.0/0 all ports. SG attached to 8 EC2 instances.', 'Unrestricted egress allows compromised instances to communicate with any external service, enabling data exfiltration.', 'Restrict outbound traffic to required destinations and ports. Use VPC endpoints for AWS service access.', '00000000-0000-0000-0000-000000000013', 'OPEN', '2026-10-08', '2026-07-26T10:00:00Z'),
  ('00000000-0000-0000-0001-000000000032', 'F-1032', '00000000-0000-0000-0000-000000000100', NULL, NULL, 'DynamoDB table lacks point-in-time recovery', 'A production DynamoDB table does not have point-in-time recovery (PITR) enabled.', 'Database', 'MEDIUM', 'DynamoDB', 'prod-sessions-table', 'us-east-1', 'DynamoDB prod-sessions-table: PointInTimeRecoverySpecification=disabled. Table size: 12 GB. Item count: 4.2M.', 'Without PITR, accidental deletes or writes cannot be rolled back, risking data loss for the sessions table.', 'Enable point-in-time recovery on the table. PITR provides continuous backups for the last 35 days.', '00000000-0000-0000-0000-000000000011', 'OPEN', '2026-09-27', '2026-07-25T09:00:00Z')
INSERT INTO findings (id, finding_id, aws_account_id, assessment_id, control_id, title, description, category, severity, resource_type, resource_id, region, evidence, business_risk, recommendation, owner_id, status, due_date, created_at) VALUES
  ('00000000-0000-0000-0001-000000000033', 'F-1033', '00000000-0000-0000-0000-000000000200', NULL, (SELECT id FROM controls WHERE control_id = 'S3-003'), 'S3 bucket lacks lifecycle policy for cost optimization', 'An S3 bucket containing build logs has no lifecycle policy, keeping all objects in standard storage indefinitely.', 'S3', 'LOW', 'S3', 's3-dev-build-logs', 'us-east-1', 'Bucket s3-dev-build-logs: 0 lifecycle rules. Object count: 89,000. Storage: 124 GB. No transition to Glacier.', 'Without lifecycle policies, storage costs grow unnecessarily as old logs remain in standard storage.', 'Add a lifecycle policy: transition to Glacier after 60 days, expire after 180 days.', '00000000-0000-0000-0000-000000000012', 'OPEN', '2026-10-20', '2026-07-24T10:00:00Z'),
  ('00000000-0000-0000-0001-000000000034', 'F-1034', '00000000-0000-0000-0000-000000000300', NULL, (SELECT id FROM controls WHERE control_id = 'IAM-004'), 'IAM user has no MFA device configured', 'An IAM user in the test account has no MFA device enrolled.', 'IAM', 'LOW', 'IAM', 'test-ci-user', 'us-east-1', 'IAM user test-ci-user: MFADevices=[], ConsoleAccess=true, LastLogin=2026-08-15.', 'Accounts without MFA are more susceptible to credential compromise.', 'Enroll a virtual MFA device for the user. Enforce MFA via IAM policy conditions.', '00000000-0000-0000-0000-000000000013', 'OPEN', '2026-10-25', '2026-07-23T11:00:00Z'),
  ('00000000-0000-0000-0001-000000000035', 'F-1035', '00000000-0000-0000-0000-000000000300', NULL, NULL, 'EKS cluster has no resource limits on default namespace', 'The default namespace in the test EKS cluster has no ResourceQuota, allowing unbounded resource consumption.', 'EKS', 'LOW', 'EKS', 'eks-test-main / default namespace', 'us-east-1', 'Namespace default: ResourceQuota=[], LimitRange=[]. 14 pods running in default namespace.', 'Without ResourceQuotas, any pod in the default namespace can consume unlimited cluster resources.', 'Apply a ResourceQuota and LimitRange to the default namespace. Move workloads to dedicated namespaces.', '00000000-0000-0000-0000-000000000012', 'OPEN', '2026-10-30', '2026-07-22T09:00:00Z'),
  ('00000000-0000-0000-0001-000000000036', 'F-1036', '00000000-0000-0000-0000-000000000300', NULL, NULL, 'CloudWatch dashboard missing for test environment', 'The test environment has no CloudWatch dashboards, making it difficult to visualize environment health.', 'Observability', 'LOW', 'CloudWatch', 'CloudWatch Dashboards', 'us-east-1', 'Account acc-test: 0 CloudWatch dashboards. 3 EC2 instances, 2 RDS instances, 1 EKS cluster with no visualization.', 'Without dashboards, monitoring the test environment requires manual log inspection, reducing efficiency.', 'Create dashboards for key resources: EKS cluster health, RDS metrics, EC2 utilization, and alarm status.', '00000000-0000-0000-0000-000000000012', 'OPEN', '2026-11-05', '2026-07-21T10:00:00Z'),
  ('00000000-0000-0000-0001-000000000037', 'F-1037', '00000000-0000-0000-0000-000000000100', NULL, NULL, 'S3 bucket inventory configuration not enabled', 'A large S3 data lake bucket does not have inventory configuration enabled.', 'S3', 'LOW', 'S3', 's3-prod-data-lake', 'us-east-1', 'Bucket s3-prod-data-lake: inventoryConfig=null. Object count: ~12M. Storage: 8.4 TB.', 'Without inventory, tracking objects in a large bucket is expensive and slow, complicating audits and lifecycle management.', 'Enable S3 Inventory with daily CSV reports to a destination bucket. Use for lifecycle and compliance auditing.', '00000000-0000-0000-0000-000000000011', 'OPEN', '2026-11-10', '2026-07-20T11:00:00Z'),
  ('00000000-0000-0000-0001-000000000038', 'F-1038', '00000000-0000-0000-0000-000000000100', NULL, NULL, 'EC2 instance has no termination protection', 'A production bastion host does not have termination protection enabled.', 'Compute', 'LOW', 'EC2', 'i-prod-bastion-01', 'us-east-1', 'Instance i-prod-bastion-01: DisableApiTermination=false. Instance is the sole bastion for SSH/SSM access to prod VPC.', 'Without termination protection, the bastion host can be accidentally terminated, cutting off administrative access.', 'Enable termination protection on the bastion host. Add a CloudWatch alarm for instance termination events.', '00000000-0000-0000-0000-000000000012', 'OPEN', '2026-11-01', '2026-07-19T09:00:00Z'),
  ('00000000-0000-0000-0001-000000000039', 'F-1039', '00000000-0000-0000-0000-000000000100', NULL, (SELECT id FROM controls WHERE control_id = 'IAM-001'), 'IAM policy contains unused permissions', 'An IAM policy grants S3 permissions to 15 buckets, but the application only accesses 3.', 'IAM', 'LOW', 'IAM', 'policy-prod-app-s3-access', 'us-east-1', 'Policy policy-prod-app-s3-access: grants ListBucket on 15 buckets. Access Analyzer shows access to only 3 buckets in last 90 days.', 'Overly broad S3 access increases the impact of credential compromise.', 'Reduce the policy to only the 3 buckets the application accesses. Use Access Analyzer data to right-size.', '00000000-0000-0000-0000-000000000013', 'OPEN', '2026-11-15', '2026-07-18T10:00:00Z'),
  ('00000000-0000-0000-0001-000000000040', 'F-1040', '00000000-0000-0000-0000-000000000300', NULL, NULL, 'EKS cluster lacks cluster-autoscaler logging', 'The cluster-autoscaler deployment in the test EKS cluster has verbose logging disabled.', 'EKS', 'LOW', 'EKS', 'eks-test-main / cluster-autoscaler', 'us-east-1', 'Deployment cluster-autoscaler in kube-system: log level=1 (info). v=4 not enabled. Recent scaling events: 7 in last week.', 'Without autoscaler logs, diagnosing scaling issues requires manual investigation.', 'Increase log verbosity to v=4 for the cluster-autoscaler. Ship logs to CloudWatch for analysis.', '00000000-0000-0000-0000-000000000012', 'OPEN', '2026-11-20', '2026-07-17T11:00:00Z')
